const defaults = { theme: "light" };
const prefs = { lang: "en" };
Object.setPrototypeOf(prefs, defaults);
console.log(prefs.theme);
Object.setPrototypeOf(prefs, null);
console.log(prefs.theme);
console.log("toString" in prefs);
try {
  console.log(String(prefs));
} catch (err) {
  console.log(err.name);
}
